args.query:
select count(*) from line_score
where try_cast(pts_qtr1_home as int) is null or try_cast(pts_qtr2_home as int) is null or try_cast(pts_qtr3_home as int) is null
or try_cast(pts_qtr1_away as int) is null or try_cast(pts_qtr2_away as int) is null or try_cast(pts_qtr3_away as int) is null;

select count(*) from (
    select game_id from line_score
    except
    select game_id from play_by_play
) t;

select count(*) from (
    select game_id from play_by_play
    except
    select game_id from line_score
) t;
